// Round-trip tests for projects whose UUIDs were rewritten by Ruby's
// `Project#predictabilize_uuids` (32-char MD5 UUIDs, as found in
// CocoaPods-generated Pods.xcodeproj files).
//
// The inputs and Ruby's own open + save of them live in
// test/fixtures/predictabilized/ and are regenerated by the generate.rb next
// to them. Annotations must not depend on the shape of the UUID.

import 'dart:io';

import 'package:dart_xcodeproj/src/project/uuid_generator.dart';
import 'package:dart_xcodeproj/src/project/xcode_project.dart';
import 'package:test/test.dart';

const _dir = 'test/fixtures/predictabilized';

/// An object reference followed by its annotation, e.g. `ABC... /* Runner */`.
final _annotatedReference = RegExp(r'\b[0-9A-F]{32} /\*');

/// A 32-char UUID not followed by an annotation.
final _bareReference = RegExp(r'\b[0-9A-F]{32}\b(?! /\*)');

void main() {
  for (final name in ['ios', 'macos_spm']) {
    group('open + save of the predictabilized $name project', () {
      late String input;
      late String ruby;
      late String saved;

      setUpAll(() async {
        input = File('$_dir/$name.predictabilized.pbxproj').readAsStringSync();
        ruby = File('$_dir/$name.ruby_saved.pbxproj').readAsStringSync();

        // Flutter's bundle is called Runner.xcodeproj; the name shows up in
        // the "Build configuration list for PBXProject" annotation.
        final tmp = Directory.systemTemp.createTempSync('predictabilized_');
        addTearDown(() => tmp.deleteSync(recursive: true));
        final bundle = Directory('${tmp.path}/Runner.xcodeproj')..createSync();
        File('${bundle.path}/project.pbxproj').writeAsStringSync(input);
        await (await XcodeProject.open(bundle.path)).save();
        saved = File('${bundle.path}/project.pbxproj').readAsStringSync();
      });

      test('the fixture uses 32-char UUIDs only', () {
        expect(_annotatedReference.allMatches(input), isNotEmpty);
        expect(
          RegExp(r'\b[0-9A-F]{24}\b').hasMatch(input),
          isFalse,
          reason: 'no 24-char UUID may remain',
        );
        expect(
          UuidGenerator.isValid(
            _annotatedReference.firstMatch(input)!.group(0)!.split(' ').first,
          ),
          isTrue,
        );
      });

      test('preserves every annotation', () {
        expect(
          _annotatedReference.allMatches(saved).length,
          equals(_annotatedReference.allMatches(input).length),
        );
      });

      test('is identical to what Ruby writes', () {
        expect(saved, equals(ruby));
      });

      test('is identical to the input', () {
        // Ruby leaves a project it has just saved untouched, and so must Dart.
        expect(saved, equals(input));
      });

      test('only annotates references where Ruby does', () {
        expect(
          _bareReference.allMatches(saved).length,
          equals(_bareReference.allMatches(ruby).length),
        );
      });
    });
  }
}
